package at.hausgarten.service;
import org.json.*;import java.util.*;import java.nio.file.*;
/** Versioned semantic audit, all registered schemas, runtime write gate and large read paths. */
public final class UiMcpParityTests {
 static int checks;static void yes(boolean b){checks++;if(!b)throw new AssertionError("parity check "+checks);}
 public static void main(String[] args)throws Exception { SyntheticBusinessData.verify();
  JSONObject state=PixelMcpWriteTests.state();PixelMcpWriteTools.Sink sink=new PixelMcpWriteTools.Sink(){public JSONObject execute(String n,JSONObject a){return SyntheticBusinessData.object();}public JSONObject status(String id,JSONObject s){return SyntheticBusinessData.object();}};
  PixelMcpReadTools tools=new PixelMcpReadTools(()->state,sink);JSONArray catalog=tools.tools();Set<String> names=new HashSet<>();
  for(int i=0;i<catalog.length();i++){JSONObject tool=catalog.getJSONObject(i);yes(names.add(tool.getString("name")));if(!tool.getJSONObject("annotations").getBoolean("readOnlyHint")){yes(tool.getJSONObject("inputSchema").getJSONArray("required").toString().contains("request_id"));yes(tool.getJSONObject("annotations").getBoolean("idempotentHint"));}}
  Files.writeString(Path.of("outputs/integration-java/source-tool-catalog.json"),catalog.toString(2));
  yes(catalog.length()==169);JSONObject capabilities=tools.call("get_capabilities",SyntheticBusinessData.object()).getJSONObject("data");yes(capabilities.getString("tool_catalog_hash").equals(PixelMcpWriteTools.hash(catalog)));yes(capabilities.getBoolean("owner_admin_write_enabled"));yes(capabilities.getString("owner_action_scope").equals("all_registered_business_and_admin_operations"));yes(!new PixelMcpReadTools(()->state).call("get_capabilities",SyntheticBusinessData.object()).getJSONObject("data").getBoolean("owner_admin_write_enabled"));
  JSONObject manifest=SyntheticBusinessData.object(Files.readString(Path.of("android/app/src/main/assets/ui-mcp-actions.json")));JSONArray actions=manifest.getJSONArray("actions");Set<String> ids=new HashSet<>();int covered=0,platform=0;
  for(int i=0;i<actions.length();i++){JSONObject row=actions.getJSONObject(i);yes(ids.add(row.getString("id")));JSONArray path=row.getJSONArray("mcp");if(row.getString("kind").equals("business")){yes(path.length()>0);covered++;for(int j=0;j<path.length();j++)yes(names.contains(path.getString(j)));}else{yes(!row.optString("barrier").isEmpty());platform++;}}
  JSONObject sources=manifest.getJSONObject("reviewed_sources");for(Iterator<String> k=sources.keys();k.hasNext();){String file=k.next();yes(sources.getString(file).equals(DriveRestClient.sha256(Files.readAllBytes(Path.of(file)))));}
  Set<String> readNames=new HashSet<>();JSONArray readonly=new PixelMcpReadTools(()->state).tools();for(int i=0;i<readonly.length();i++){JSONObject t=readonly.getJSONObject(i);readNames.add(t.getString("name"));yes(t.getJSONObject("annotations").getBoolean("readOnlyHint"));}for(String n:new String[]{"finish_work","save_reviewed_order","update_planning_settings","purge_entity","close_legacy_conflicts"})yes(!readNames.contains(n));
  for(String n:new String[]{"close_legacy_conflicts","purge_entity","empty_trash","request_invoice_issue"}){JSONObject invalid=SyntheticBusinessData.object().put("request_id","synthetic-unsafe").put("confirmed",false);boolean denied=false;try{PixelMcpOwnerTools.validate(n,invalid);}catch(Exception e){denied=true;}yes(denied);}
  JSONArray photos=new JSONArray();for(int i=0;i<125;i++)photos.put(SyntheticBusinessData.object().put("id","qa_p"+String.format("%03d",i)).put("customer_id","qa_c1").put("capture_time","2026-10-19T08:00:00Z").put("role",i%2==0?"before":"after"));state.getJSONObject("master").put("photos",photos);
  Set<String> seen=new HashSet<>();for(int offset=0;offset<125;offset+=30){JSONArray page=tools.call("list_photos",SyntheticBusinessData.object().put("customer_id","qa_c1").put("limit",30).put("offset",offset)).getJSONObject("data").getJSONArray("photos");yes(page.length()<=30);for(int i=0;i<page.length();i++)yes(seen.add(page.getJSONObject(i).getString("id")));}yes(seen.size()==125);
  JSONArray before=tools.call("list_photos",SyntheticBusinessData.object().put("customer_id","qa_c1").put("role","before").put("limit",100)).getJSONObject("data").getJSONArray("photos");yes(before.length()==63);
  System.out.println("SOURCE_CATALOG_HASH "+PixelMcpWriteTools.hash(catalog));System.out.println("SOURCE_UI_CATALOG_HASH "+PixelMcpWriteTools.hash(manifest));System.out.println("PASS "+checks+" parity checks; semantic UI actions="+actions.length()+", MCP-covered="+covered+", explicit platform/presentation groups="+platform+", source tools="+catalog.length());
 }
}
